if (const auto* error = job.FindString("error")) result.Set("errorMessage", *error);
if (const auto* source = job.FindString("sourceId"); source && *source == "atlas")
  result.Set("sourceId", "chatgpt-atlas");

const auto* id = source.GetDict().FindString("id");
const bool file_import = id && *id == "safari";
if (id && *id == "atlas")
  source.GetDict().Set("id", "chatgpt-atlas");
if (file_import)
  source.GetDict().Set("requiresFileImport", true);
else
  source.GetDict().Remove("requiresFileImport");
// Original4278274 exposes this list; the supplied settings picker calls
// includes() on it. Advertise only real current migrator capabilities.
base::ListValue supported;
if (const auto* categories = source.GetDict().FindList("categories")) {
  for (const char* kind : {"history", "bookmarks", "passwords", "cookies",
                           "autofill"}) {
    if (std::ranges::find(*categories, base::Value(kind)) != categories->end())
      supported.Append(kind);
  }
}
source.GetDict().Set("supportedDataKinds", std::move(supported));

const auto *source_id = options.FindString("sourceId"),
           *profile_id = options.FindString("sourceProfileId");
std::string internal_source_id;
if (source_id && *source_id == "chatgpt-atlas") {
  internal_source_id = "atlas";
  source_id = &internal_source_id;
}
